  assert.equal(result.cleanupUnverified, false);
  assert.equal(Buffer.concat(output).toString(), "nested retired");
  const { pid } = JSON.parse(await readFile(f.ready, "utf8"));
  assert.throws(() => process.kill(pid, 0), { code: "ESRCH" });
});

